const $in = $input.first().json;

const code = String($in.query?.code ?? '').trim().toUpperCase();
if (!/^[A-Z0-9]{6}$/.test(code)) return [{ json: { ok: false, status: 404, body: { success: false, message: 'Tournament not found.' } } }];
return [{ json: { ok: true, code } }];

const b2 = $('Authorize B2').isExecuted ? $('Authorize B2').first().json : {};
const dl = b2?.apiInfo?.storageApi?.downloadUrl;
const tokenOf = node => { try { return $(node).isExecuted ? $(node).first().json.authorizationToken : null; } catch { return null; } };
const signWith = (key, node) => { const t = tokenOf(node); return key && dl && t ? `${dl}/file/mypaltan-profile-photos/${key.split('/').map(encodeURIComponent).join('/')}?Authorization=${t}` : null; };
const parseJ = v => { if (v === null || v === undefined) return null; if (typeof v === 'object') return v; try { return JSON.parse(v); } catch { return null; } };

const t = $('Load Tournament').first().json;
const A = k => signWith(k, 'Assets Link');
const sponsors = (parseJ(t.sponsors) || []).sort((a, b) => a.sort_order - b.sort_order).map(s => ({
  id: s.id, name: s.name, label: s.label, is_title: Number(s.is_title) === 1, logo_url: A(s.logo_key), banner_url: A(s.banner_key),
  link_url: s.link_url || null, tagline: s.tagline || null }));
const documents = (parseJ(t.documents) || []).sort((a, b) => a.sort_order - b.sort_order).map(d => ({
  doc_type: d.doc_type, title: d.title, mime_type: d.mime_type, url: A(d.file_key) }));
const tournament = {
  code: t.code, sport: t.sport, name: t.name, description: t.description || null, logo_url: A(t.logo_key), banner_url: A(t.banner_key),
  category: t.category, city: t.city, area: t.area, start_date: t.start_date, end_date: t.end_date, match_days: t.match_days, match_timing: t.match_timing,
  format: t.format, group_count: t.group_count, qualify_per_group: t.qualify_per_group, max_teams: t.max_teams, squad_min: t.squad_min, squad_max: t.squad_max,
  entry_fee: Number(t.entry_fee), prize_type: t.prize_type, prize_details: t.prize_details || null,
  food_provided: Number(t.food_provided) === 1, meals: t.meals ? String(t.meals).split(',') : [], jersey_provided: Number(t.jersey_provided) === 1,
  registration_deadline: t.registration_deadline, status: t.status, listed: t.visibility === 'PUBLIC',
  approved_teams: Number(t.approved_teams || 0), match_rules: parseJ(t.match_rules) || {}, grounds: parseJ(t.grounds) || [],
  organizer: { name: t.organizer_name, verified: Number(t.organizer_verified) === 1 }, sponsors, documents,
};
return [{ json: { status: 200, body: { success: true, tournament } } }];
